// doc2.js: "Behind the Badge" episodes you can open: title, summary, the plot scene by scene, the drama and quotes.
// Episodes are built from what actually happened (results, scorers, table, injuries, the next game). Quotes come only
// from fictional people: you (the manager), your staff, a kit man and a groundsman invented for the series, academy
// players generated by the game, and the narrator. Real players appear in the narration of match events.
// Replaces docWeek() from clublife.js. Loaded after wff.js.

function docCtx() {
  const t = userTeam(); const sq = squad(G.user);
  const fx = Object.values(G.fx).filter(f => f.r && (f.h === G.user || f.a === G.user) && f.d <= G.date && f.d >= addDays(G.date, -14) && f.comp !== 'PSF').sort((a, b) => a.d < b.d ? -1 : 1);
  const desc = (f) => {
    const home = f.h === G.user; const us = home ? f.r[0] : f.r[1], them = home ? f.r[1] : f.r[0]; const opp = home ? f.a : f.h; const side = home ? 0 : 1;
    const sc = (f.sc || []).filter(e => e[2] === 'G' && e[1] === side && P(e[3])).map(e => surname(P(e[3]).n));
    const res = us > them ? 'win' : us < them ? 'defeat' : 'draw';
    return { res, txt: `${us}-${them} ${res === 'win' ? 'win over' : res === 'defeat' ? 'defeat to' : 'draw with'} ${tName(opp, false)}${sc.length ? ` (${[...new Set(sc)].join(', ')})` : ''}`, opp, comp: COMP_NAME[f.comp] || f.comp };
  };
  const last = fx.length ? desc(fx[fx.length - 1]) : null; const prev = fx.length > 1 ? desc(fx[fx.length - 2]) : null;
  const L = lgRow(G.user); const inj = sq.filter(p => p.inj > 0); const top = sq.slice().sort((a, b) => b.st.g - a.st.g)[0];
  const nx = Object.values(G.fx).filter(f => !f.r && (f.h === G.user || f.a === G.user) && f.d > G.date).sort((a, b) => a.d < b.d ? -1 : 1)[0];
  const kids = sq.filter(p => p.gen && p.age <= 21).concat((typeof youthIds === 'function' ? youthIds(G.user) : []).map(P).filter(p => p && p.gen && p.c === G.user)).slice(0, 6);
  return { t, sq, last, prev, L, inj, top, nx, kid: kids.length ? R.pick(kids) : null, asst: (G.staff && G.staff.asst && G.staff.asst.n) || 'the assistant manager' };
}
function docEpisode(ev, p) {
  const D = G.doc; const c = docCtx(); const t = c.t; const m = G.mgr;
  D.kit = D.kit || genName(); D.gm = D.gm || genName();
  const res = c.last ? c.last.res : null;
  const pos = c.L && c.L.r.p >= 3 ? `${t.name} sit ${ordinal(c.L.pos)} in the ${COMP_NAME[c.L.d] || 'league'}.` : 'The season has barely started.';
  const titles = { rant: res === 'defeat' ? 'Not Good Enough' : 'Standards', tension: 'Behind Closed Doors', star: 'The Main Character', fans: 'The Twelfth Man' };
  const title = `Episode ${D.ep}: "${titles[ev]}"`;
  const open = c.last ? `The episode opens in the tunnel after the ${c.last.txt} in the ${c.last.comp}.${c.prev ? ` It follows the ${c.prev.txt}.` : ''}` : 'The episode opens on a quiet morning at the training ground.';
  const scenes = [['Cold open', open]];
  const quotes = [];
  if (ev === 'rant') {
    scenes.push([res ? 'Half-time' : 'Training ground meeting', `Cameras catch ${m} slamming the tactics board in the dressing room. ${res === 'win' ? 'The response in the second half is immediate.' : res ? 'The players sit in silence; nobody looks up.' : 'It is only a training session, but nobody is laughing.'}`]);
    quotes.push([m, 'Manager', res === 'defeat' ? 'That is not who we are. If you want to wear this shirt, you run until you drop. Every single one of you.' : res === 'win' ? 'We won, fine. But if we play like that against a good side, we get punished. I want more.' : res === 'draw' ? 'A point. A point! We had them there and we let them off. Not again.' : 'Pre-season is where you decide what kind of team you are. Right now I don\'t know. Show me.']);
    quotes.push([c.asst, 'Assistant manager', 'When he goes like that, you just let it land. Ten minutes later he\'s hugging everyone.']);
  } else if (ev === 'tension') {
    scenes.push(['The row', `After being left out of the starting line-up, ${p.n} is seen in a heated exchange with the coaching staff on the training pitch. ${c.asst} steps in to separate them.`]);
    quotes.push([m, 'Manager', `Nobody is bigger than ${t.name}. I pick the team that gives us the best chance to win, and that is the end of it.`]);
    quotes.push([c.asst, 'Assistant manager', 'Frustration is fine. Showing it in front of the whole squad is not.']);
  } else if (ev === 'star') {
    scenes.push(['A day in the life', `The camera follows ${p.n} from the gym at 7am to an evening visit to a local school. Team-mates queue up to tease him in the canteen.`]);
    quotes.push([D.kit, 'Kit man (series)', `${surname(p.n)} is the first in and the last out. Always asks how my kids are doing.`]);
    quotes.push([m, 'Manager', `Players like ${surname(p.n)} set the standard. The young lads watch everything he does.`]);
  } else {
    scenes.push(['Matchday', `A family from the season-ticket waiting list gets the call they have waited eleven years for. The cameras follow them from the pub to their seats.`]);
    quotes.push([D.gm, 'Head groundsman (series)', 'You hear the roar from the tunnel and the hair on your arms stands up. Thirty years and it never gets old.']);
    quotes.push([m, 'Manager', 'Those people pay their money and give us everything. The least we can do is leave everything out there.']);
  }
  scenes.push(['Training ground', `${c.inj.length ? `The medical team is dealing with ${c.inj.length} injur${c.inj.length > 1 ? 'ies' : 'y'}${c.inj[0] ? `, with ${c.inj[0].n} the latest worry` : ''}. ` : 'A rare clean bill of health for the squad. '}${c.top && c.top.st.g ? `${c.top.n} leads the scoring charts with ${c.top.st.g} this season.` : ''}`]);
  if (c.kid) quotes.push([c.kid.n, 'Academy player', R.pick([`Training with the first team this week was mad. I just tried not to give the ball away.`, `The gaffer told me to stay ready. That's all I'm doing, staying ready.`, `My mum's watching this, so I'm on my best behaviour.`])]);
  scenes.push(['Closing', `${pos}${c.nx ? ` Next up: ${tName(c.nx.h === G.user ? c.nx.a : c.nx.h, false)} (${COMP_NAME[c.nx.comp] || c.nx.comp}) on ${dShort(c.nx.d)}.` : ''} The narrator closes the episode: "In this building, there is no such thing as a quiet week."`]);
  quotes.push(['Narrator', 'Series voice-over', R.pick(['Every club tells itself a story. This one is still deciding how it ends.', 'Results decide everything here. Even the mood in the canteen.', 'Behind every badge there is a dressing room. Behind every dressing room, a secret.'])]);
  const drama = clamp((ev === 'tension' ? 4 : ev === 'rant' ? 3 : 2) + (res === 'defeat' ? 1 : 0), 1, 5);
  const talk = ev === 'tension' ? `Social media splits over ${surname(p.n)}: some fans back him, others say no player should react like that.` : ev === 'rant' ? 'The half-time team talk becomes the most-watched clip of the series so far.' : ev === 'star' ? `${surname(p.n)} trends as viewers fall for his personality.` : 'Viewers call it the most moving episode of the series.';
  const summary = ev === 'tension' ? `Tension at ${t.name} as ${p.n} clashes with the coaching staff.` : ev === 'rant' ? `${m} lets rip at half-time${res === 'defeat' ? ' after a painful defeat' : ''}.` : ev === 'star' ? `${p.n} steals the show off the pitch.` : `The supporters take centre stage.`;
  return { n: D.ep, d: G.date, ev, title, summary, scenes, quotes, drama, talk, pid: p ? p.id : null };
}
// the weekly hook (same effects as before, plus the episode record)
docWeek = function () {
  const D = G.doc; if (!D || D.y !== G.year || D.tid !== G.user || !R.chance(.3)) return;
  D.ep++; const sq = squad(G.user); const p = R.pick(sq);
  const ev = R.pick(['rant', 'tension', 'star', 'fans']);
  if (ev === 'rant') { for (const q of sq) q.mor = clamp(q.mor + R.i(-3, 4), 5, 100); fanPost(G.user, `Episode ${D.ep} of ${DOC_NAME}: the half-time team talk is going viral 😳🔥`, { big: true }); trend(DOC_NAME.replace(/ /g, ''), 3); }
  else if (ev === 'tension') { setHap(p, -6); fanPost(G.user, `That ${surname(p.n)} scene in ${DOC_NAME}... 👀 drama`, { big: true }); }
  else if (ev === 'star') { setHap(p, 5); p.mor = clamp(p.mor + 6, 5, 100); fanPost(G.user, `${surname(p.n)} is the star of ${DOC_NAME}. What a character 😂❤️`, { big: true }); }
  else { G.fans = clamp((G.fans ?? 60) + 2, 0, 100); const t = userTeam(); const b = Math.round(t.rep * 0.02 * 10) / 10; t.bal += b; t.fin.in.com += b; fanPost(G.user, `Binge-watched ${DOC_NAME} in one night. Proud of this club 💙`); }
  try { const e = docEpisode(ev, p); D.eps = (D.eps || []).concat(e); news('Media', `${DOC_NAME} — ${e.title}. ${e.summary}`, G.user); const nw = G.news.find(x => x.id === G.newsId); if (nw) nw.act = { k: 'doc', i: D.eps.length - 1 }; } catch (e) { console.error(e); }
};
function docEpHtml(i) {
  const D = G.doc; const e = D && D.eps && D.eps[i]; if (!e) return '';
  return `<div class="band"><span>${esc(DOC_NAME)} · ${esc(userTeam().name)}</span><button class="x" data-a="close" aria-label="Close">×</button></div><div class="mc">
  <h2 style="margin:0">${esc(e.title)}</h2><div class="dim">${dShort(e.d)} · Drama ${'🔥'.repeat(e.drama)}${'·'.repeat(5 - e.drama)}</div>
  <p style="font-size:15px"><b>${esc(e.summary)}</b></p>
  <h2 class="sect">The episode</h2>${e.scenes.map(([h, x]) => `<div style="margin:8px 0"><span class="lb">${esc(h)}</span><div>${esc(x)}</div></div>`).join('')}
  <h2 class="sect">Quotes</h2>${e.quotes.map(([who, role, q]) => `<blockquote style="margin:8px 0;padding:6px 10px;border-left:3px solid var(--yel)">"${esc(q)}"<div class="dim" style="font-size:12px;margin-top:2px">— ${esc(who)}, ${esc(role)}</div></blockquote>`).join('')}
  <h2 class="sect">Talking point</h2><p>${esc(e.talk)}</p>
  <div class="row" style="margin-top:10px">${i > 0 ? `<button class="btn" data-a="docep" data-v="${i - 1}">‹ Episode ${D.eps[i - 1].n}</button>` : ''}${i < D.eps.length - 1 ? `<button class="btn" data-a="docep" data-v="${i + 1}">Episode ${D.eps[i + 1].n} ›</button>` : ''}</div>
  <p class="dim" style="font-size:12px">The series' quotes come from you, your staff, invented crew members and academy players; real players appear only in the narration.</p></div>`;
}
ACT.docep = (v) => { UI.modal = docEpHtml(+v); render(); };
const _maDoc = msgActions;
msgActions = function (m) { if (m && m.act && m.act.k === 'doc') return `<div class="row" style="margin-top:12px"><button class="btn pri" data-a="docep" data-v="${m.act.i}">Episode summary</button></div>`; return _maDoc(m); };
const _cbDoc = scrClubBoard;
scrClubBoard = function () {
  let h = _cbDoc(); const D = G.doc && G.doc.y === G.year && G.doc.tid === G.user ? G.doc : null;
  if (D && D.eps && D.eps.length) h += `<div class="box pad" style="margin-top:10px"><h3 class="h3">${esc(DOC_NAME)}: episodes</h3><div class="tw"><table class="t"><tbody>${D.eps.map((e, i) => `<tr class="click" data-a="docep" data-v="${i}"><td class="mono dim">${dShort(e.d)}</td><td><b>${esc(e.title)}</b><div class="dim" style="font-size:12px;white-space:normal">${esc(e.summary)}</div></td><td>${'🔥'.repeat(e.drama)}</td></tr>`).join('')}</tbody></table></div></div>`;
  return h;
};
